export const HRVATSKA_QUIZ_COUNT = hrvatskaQuiz.length;

export function getHrvatskaQuestion(index) {
  return hrvatskaQuiz[index] ?? null;
}

export function getRandomHrvatskaQuestions(count = 10) {
  const questions = [...hrvatskaQuiz];
  for (let i = questions.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    [questions[i], questions[j]] = [questions[j], questions[i]];
  }
  return questions.slice(0, Math.max(0, Math.min(count, questions.length)));
}

export default hrvatskaQuiz;
